/**
 * Live, still-open issues whose due date has passed, in projects that are not
 * archived (an archived project freezes its issues). Drives the overdue job.
 */
export async function listOverdueIssues(
  orgId: OrgId,
  now: IsoTimestamp,
): Promise<readonly Issue[]> {
  const liveProjectIds = getDb()
    .select({ id: projects.id })
    .from(projects)
    .where(and(...compact(livePredicate(projects.archivedAt, {}))));

  const rows = getDb()
    .select()
    .from(issues)
    .where(
      and(
        ...compact(
          orgPredicate(issues.orgId, orgId),
          livePredicate(issues.archivedAt, {}),
          inArray(issues.projectId, liveProjectIds),
          isNotNull(issues.dueAt),
          lt(issues.dueAt, now),
          inArray(issues.status, ["backlog", "todo", "in_progress", "in_review"]),
        ),
      ),
    )

